// Show or hide the Save & Add Another Plot button based on context
function setSaveNextPlotButtonVisibility(visible) {
  const btn = document.getElementById('save-next-plot-btn');
  if (!btn) return;
  btn.style.display = visible ? 'flex' : 'none';
}
function showAuth(type){document.getElementById('welcome-page').classList.add('hidden');document.getElementById('auth-page').classList.add('visible');switchAuth(type);clearInterval(slideTimer)}
function switchAuth(type){const signupEnabled=!!document.getElementById('signup-form');const login=!signupEnabled||type==='login';document.getElementById('login-tab')?.classList.toggle('active',login);document.getElementById('signup-tab')?.classList.toggle('active',!login);document.getElementById('login-form')?.classList.toggle('active',login);document.getElementById('signup-form')?.classList.toggle('active',!login);document.getElementById('auth-title').textContent=login?'Sign In':'Create Account'}
function setAuthFeedback(message='',type='info'){const el=document.getElementById('auth-feedback');if(!el)return;if(!message){el.textContent='';el.className='auth-feedback';return}el.textContent=message;el.className=`auth-feedback ${type} visible`}
function formatApiError(detail,fallback='Request failed'){if(!detail)return fallback;if(typeof detail==='string')return detail;if(Array.isArray(detail))return detail.map(item=>{if(typeof item==='string')return item;const loc=Array.isArray(item?.loc)?item.loc.filter(part=>part!=='body').join('. '):'';const msg=item?.msg||item?.message||JSON.stringify(item);return loc?`${loc}: ${msg}`:msg}).join(' ');if(typeof detail==='object')return detail.msg||detail.message||JSON.stringify(detail);return fallback}
function setBusyButtonState(buttonId,isBusy,busyText=''){const btn=typeof buttonId==='string'?document.getElementById(buttonId):buttonId;if(!btn)return null;if(isBusy){btn.disabled=true;btn._originalHTML=btn.innerHTML;btn._originalDisabled=false;if(busyText)btn.innerHTML=busyText}else{btn.disabled=btn._originalDisabled||false;if(btn._originalHTML)btn.innerHTML=btn._originalHTML}return btn}
function setLoginSubmitting(isSubmitting){const form=document.getElementById('login-form');if(!form)return;const inputs=form.querySelectorAll('input[type="text"], input[type="password"]');inputs.forEach(input=>input.disabled=isSubmitting)}
async function fetchSystemInfo(){try{const r=await fetch(`${API_URL}/system/info`);if(!r.ok)throw new Error('offline');serverInfo=await r.json();renderOperationsPanel('Online')}catch{serverInfo=null;renderOperationsPanel('Offline')}}
function renderOperationsPanel(connectionLabel){const appVersion=document.getElementById('ops-app-version'),serverVersion=document.getElementById('ops-server-version'),collector=document.getElementById('ops-collector'),connection=document.getElementById('ops-connection'),postgis=document.getElementById('ops-postgis'),lastSync=document.getElementById('ops-last-sync');if(appVersion)appVersion.textContent=APP_VERSION;if(serverVersion)serverVersion.textContent=currentUser&&currentUser.isGuest?'Local session':(serverInfo&&serverInfo.app_version?serverInfo.app_version:'Unavailable');if(collector)collector.textContent=currentUser?currentUser.displayName:'Not signed in';if(connection)connection.textContent=currentUser&&currentUser.isGuest?'Local only':(connectionLabel||'Unknown');if(postgis)postgis.textContent=currentUser&&currentUser.isGuest?'Not used in guest mode':(serverInfo&&serverInfo.postgis_version?serverInfo.postgis_version:'Unavailable');if(lastSync)lastSync.textContent=lastSyncMessage;renderSyncHistory()}
function saveSyncHistory(){localStorage.setItem(SYNC_HISTORY_KEY,JSON.stringify(syncHistory.slice(0,10)))}
function formatSyncHistoryTime(value){const when=new Date(value);return Number.isNaN(when.getTime())?'':when.toLocaleString()}
function renderSyncHistory(){const list=document.getElementById('ops-history-list');if(!list)return;list.innerHTML='';if(!syncHistory.length){list.innerHTML='<li class="ops-history-item empty">No sync activity yet.</li>';return}syncHistory.slice(0,10).forEach(item=>{const li=document.createElement('li');li.className=`ops-history-item ${item.type||'info'}`;li.innerHTML=`<span class="ops-history-message">${item.message}</span><span class="ops-history-time">${formatSyncHistoryTime(item.at)}</span>`;list.appendChild(li)})}
function addSyncHistory(type,message){syncHistory=[{type:type||'info',message,at:new Date().toISOString()},...syncHistory].slice(0,10);saveSyncHistory()}
function setLastSyncMessage(message,type='info'){lastSyncMessage=message;addSyncHistory(type,message);renderOperationsPanel(serverInfo?'Online':'Offline')}
let backgroundSyncInFlight=false;
function hasPendingLocalEntries(){return getPendingSyncQueue().length>0}
function canRunBackgroundSync(){return !!(isNetworkLikelyAvailable()&&accessToken&&currentUser&&!currentUser.isGuest&&hasRole('collector','admin')&&hasPendingLocalEntries())}
async function runBackgroundSync(reason='online'){if(backgroundSyncInFlight||!canRunBackgroundSync())return false;backgroundSyncInFlight=true;try{await pushAllPending({silent:true,reason});return true}finally{backgroundSyncInFlight=false}}
function handleConnectivityChange(){updateOfflineStatus();if(navigator.onLine){setLastSyncMessage('Connection restored. Checking pending entries for background sync.','info');runBackgroundSync('connectivity-restored').catch(()=>{})}else setLastSyncMessage('You are offline. Local collection will continue and sync can resume when connection returns.','warning')}
function registerBackgroundSyncAutopilot(){if(registerBackgroundSyncAutopilot.bound)return;window.addEventListener('online',handleConnectivityChange);window.addEventListener('offline',handleConnectivityChange);registerBackgroundSyncAutopilot.bound=true}
function logout(){
  localStorage.removeItem(ACCESS_TOKEN_KEY);
  accessToken=null;
  currentUser=null;
  selectedEntryId=null;
  document.getElementById('app').classList.remove('visible');
  document.getElementById('auth-page').classList.remove('visible');
  document.getElementById('welcome-page').classList.remove('hidden');
  document.getElementById('username-display').textContent='Guest User';
  document.getElementById('logout-btn').style.display='none';
  document.getElementById('admin-link').style.display='none';
  hideCollectorFeedback();
  refreshCollectorQuickMenu();
  setMode('collect');
  setupSlides();
  setLastSyncMessage('Logged out successfully.','info');
  feather.replace();
}
function hasRole(...roles){return !!currentUser&&!currentUser.isGuest&&roles.includes(currentUser.role)}
function applyRolePermissions(){const canCollect=(!currentUser||currentUser.isGuest)||hasRole('collector','admin');const canValidate=hasRole('validator','admin');const isAdmin=hasRole('admin');const isGuest=!!(currentUser&&currentUser.isGuest);const collectBtn=document.getElementById('mode-collect');const validateBtn=document.getElementById('mode-validate');const collectForm=document.getElementById('collect-form');const validateForm=document.getElementById('validate-form');const adminLink=document.getElementById('admin-link');const pushAllBtn=document.getElementById('push-all-server');const shpBtn=document.getElementById('export-shp');collectBtn.style.display=canCollect?'flex':'none';validateBtn.style.display=canValidate?'flex':'none';adminLink.style.display=isAdmin?'inline-flex':'none';if(pushAllBtn){pushAllBtn.style.display=isGuest?'none':'flex';pushAllBtn.disabled=isGuest}if(shpBtn){shpBtn.style.display=isGuest?'none':'flex';shpBtn.disabled=isGuest}const modeHeader=collectBtn?.closest('.section')?.querySelector('h2');if(modeHeader){modeHeader.style.display=canValidate?'':'none';if(!canValidate){modeHeader.style.cursor='default';const sectionToggle=modeHeader.querySelector('.section-toggle');if(sectionToggle)sectionToggle.style.display='none'}else{modeHeader.style.cursor='pointer';const sectionToggle=modeHeader.querySelector('.section-toggle');if(sectionToggle)sectionToggle.style.display=''}}const modeToggle=document.querySelector('.mode-toggle');if(modeToggle){modeToggle.style.display=canValidate?'flex':'none'}if(canCollect){collectBtn.classList.add('active');validateBtn.classList.remove('active');syncModePanels(true)}else if(canValidate){collectBtn.classList.remove('active');validateBtn.classList.add('active');syncModePanels(false)}else{collectBtn.classList.remove('active');validateBtn.classList.remove('active');if(collectForm){collectForm.style.display='none';collectForm.hidden=true}if(validateForm){validateForm.style.display='none';validateForm.hidden=true}}refreshCollectorQuickMenu()}
async function restoreSession(){if(!accessToken)return false;try{const r=await fetch(`${API_URL}/auth/me`,{headers:{Authorization:`Bearer ${accessToken}`}});if(!r.ok)throw new Error();const me=await r.json();currentUser={displayName:me.full_name||me.username,username:me.username,role:me.role||'collector',isGuest:false};startApp();return true}catch{localStorage.removeItem('access_token');accessToken=null;return false}}
async function login(){const username=document.getElementById('login-username').value.trim();const password=document.getElementById('login-password').value;if(!username||!password){setAuthFeedback('Please fill in your username and password.','error');return}const payload=new URLSearchParams();payload.set('username',username);payload.set('password',password);setAuthFeedback('Signing in...','info');setLoginSubmitting(true);setBusyButtonState('login-submit-btn',true,'<i data-feather="loader"></i> Signing In...');try{const r=await fetch(`${API_URL}/auth/login/access-token`,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:payload.toString()});const data=await r.json();if(!r.ok)throw new Error(formatApiError(data.detail,'Login failed'));accessToken=data.access_token;localStorage.setItem('access_token',accessToken);let me=null;try{const meResponse=await fetch(`${API_URL}/auth/me`,{headers:{Authorization:`Bearer ${accessToken}`}});if(meResponse.ok)me=await meResponse.json()}catch{}currentUser={displayName:me?.full_name||me?.username||username,username:me?.username||username,role:me?.role||'collector',isGuest:false};setAuthFeedback('Signed in. Opening the collector...','info');startApp()}catch(e){document.getElementById('login-password').value='';setAuthFeedback(`Login failed: ${e.message}`,'error')}finally{setLoginSubmitting(false);setBusyButtonState('login-submit-btn',false)}}
window.login=login;
window.setAuthFeedback=setAuthFeedback;
window.signup=signup;
function startGuest(){localStorage.removeItem('access_token');accessToken=null;currentUser={displayName:'Guest User',username:'Guest User',isGuest:true};startApp()}
async function signup(){const username=document.getElementById('signup-username').value.trim();const email=document.getElementById('signup-email').value.trim();const password=document.getElementById('signup-password').value;const confirmPassword=document.getElementById('signup-confirm-password').value;if(!username||!email||!password||!confirmPassword){setAuthFeedback('Please fill in all fields.','error');return}if(username.length<3){setAuthFeedback('Username must be at least 3 characters.','error');return}if(password!==confirmPassword){setAuthFeedback('Passwords do not match.','error');return}if(password.length<6){setAuthFeedback('Password must be at least 6 characters.','error');return}setAuthFeedback('Creating account...','info');try{const r=await fetch(`${API_URL}/auth/signup`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username,email,password,full_name:username})});const data=await r.json();if(!r.ok)throw new Error(formatApiError(data.detail,'Signup failed'));accessToken=data.access_token;localStorage.setItem('access_token',accessToken);let me=null;try{const meResponse=await fetch(`${API_URL}/auth/me`,{headers:{Authorization:`Bearer ${accessToken}`}});if(meResponse.ok)me=await meResponse.json()}catch{}currentUser={displayName:me?.full_name||me?.username||username,username:me?.username||username,role:me?.role||'collector',isGuest:false};setAuthFeedback('Account created! Opening the collector...','info');startApp()}catch(e){setAuthFeedback(`Signup failed: ${e.message}`,'error')}}
