function authHeaders(extra={}){return {...extra,Authorization:`Bearer ${accessToken}`}}
function migrateLegacyQueue(){if(!localStorage.getItem(LOCAL_QUEUE_KEY)&&localStorage.getItem(LEGACY_GUEST_KEY)){localStorage.setItem(LOCAL_QUEUE_KEY,localStorage.getItem(LEGACY_GUEST_KEY));localStorage.removeItem(LEGACY_GUEST_KEY)}}
function getLocalQueue(){return localQueueInMemory}
function setLocalQueue(items){localQueueInMemory=items;saveQueueToIndexedDB(items);try{localStorage.setItem(LOCAL_QUEUE_KEY,JSON.stringify(items))}catch(e){}}

function createStableLocalId(prefix='local'){
  const randomPart=typeof crypto!=='undefined'&&crypto.randomUUID?crypto.randomUUID():`${Date.now()}-${Math.random().toString(16).slice(2)}`;
  return `${prefix}-${randomPart}`;
}
function getNowIso(){return new Date().toISOString()}
function normalizeSyncMetadata(entry={}){
  const now=getNowIso();
  const localId=entry.localId||entry.local_id||createStableLocalId('local');
  return {
    ...entry,
    localId,
    serverId:entry.serverId||entry.server_id||entry.id||null,
    deviceId:entry.deviceId||entry.device_id||getCollectorDeviceId(),
    syncStatus:entry.syncStatus||entry.sync_status||'pending',
    createdOffline:entry.createdOffline??entry.created_offline??true,
    createdAtLocal:entry.createdAtLocal||entry.created_at_local||entry.createdAt||now,
    updatedAtLocal:now,
    lastSyncAttempt:entry.lastSyncAttempt||entry.last_sync_attempt||'',
    syncAttemptCount:Number(entry.syncAttemptCount??entry.sync_attempt_count??0)||0,
    lastSyncError:entry.lastSyncError||entry.last_sync_error||'',
    syncLockId:entry.syncLockId||null
  };
}
function markQueueItem(localId,changes={}){
  const queue=getLocalQueue().map(entry=>{
    if(String(entry.localId)!==String(localId))return entry;
    return normalizeSyncMetadata({...entry,...changes,updatedAtLocal:getNowIso()});
  });
  setLocalQueue(queue);
}
function shouldRetrySync(entry={}){
  const status=entry.syncStatus||'pending';
  if(status==='synced'||status==='in_progress')return false;
  return true;
}
function getPendingSyncQueue(){
  return getLocalQueue()
    .map(entry=>(window.normalizeLocalEntry||normalizeLocalEntry)(entry))
    .map(normalizeSyncMetadata)
    .filter(shouldRetrySync);
}
function isNetworkLikelyAvailable(){
  return navigator.onLine!==false;
}
function getSyncErrorMessage(error){
  if(!error)return'Unknown sync error';
  if(typeof error==='string')return error;
  return error.message||String(error)||'Unknown sync error';
}

function queueEntry(entry){const queue=getLocalQueue().map(normalizeSyncMetadata);const normalized=normalizeSyncMetadata({...entry,collectedAsGuest:entry.collectedAsGuest??!!(currentUser&&currentUser.isGuest)});const filtered=queue.filter(item=>String(item.localId)!==String(normalized.localId));filtered.unshift(normalized);setLocalQueue(filtered)}
function removeQueuedEntry(localId){setLocalQueue(getLocalQueue().filter(entry=>String(entry.localId)!==String(localId)))}
function updateQueuedEntry(localId,changes){markQueueItem(localId,changes)}
