function normalizeGeofenceForEntry(result){
  const fallback={geofenceStatus:'gps_not_verified',gpsVerified:false,gpsLatitude:null,gpsLongitude:null,gpsAccuracyMeters:null,distanceToFieldMeters:null,geofenceRequiresReview:true,geofenceMessage:'GPS unavailable; geofence check skipped.'};
  if(!result)return fallback;
  const state=String(result.state||'gps-skipped').replace(/-/g,'_');
  return {
    geofenceStatus:state,
    gpsVerified:result.gpsVerified!==false && state!=='gps_skipped',
    gpsLatitude:Number.isFinite(Number(result.gpsLatitude))?Number(result.gpsLatitude):null,
    gpsLongitude:Number.isFinite(Number(result.gpsLongitude))?Number(result.gpsLongitude):null,
    gpsAccuracyMeters:Number.isFinite(Number(result.gpsAccuracyMeters))?Number(result.gpsAccuracyMeters):null,
    distanceToFieldMeters:Number.isFinite(Number(result.distance))?Number(result.distance):null,
    geofenceRequiresReview:!!result.requiresReview || state==='outside_field' || state==='near_boundary' || state==='gps_skipped',
    geofenceMessage:result.message||''
  };
}
function buildGeofenceNote(geofence={}){
  const status=geofence.geofenceStatus||'gps_not_verified';
  const distance=Number.isFinite(Number(geofence.distanceToFieldMeters))?` | Distance: ${Math.round(Number(geofence.distanceToFieldMeters))} m`:'';
  const accuracy=Number.isFinite(Number(geofence.gpsAccuracyMeters))?` | GPS accuracy: ${Math.round(Number(geofence.gpsAccuracyMeters))} m`:'';
  return `[Geofence: ${status}${distance}${accuracy}]`;
}
function applyGeofenceToDraft(draft,geofence){
  const normalized=normalizeGeofenceForEntry(geofence);
  Object.assign(draft,normalized);
  if(normalized.geofenceRequiresReview){
    draft.validationStatus='uncertain';
    draft.reviewStatus='pending_review';
    const existing=String(draft.notes||'').trim();
    const note=buildGeofenceNote(normalized);
    draft.notes=existing?`${existing}\n${note}`:note;
  }
  return draft;
}

