function updateValidationTarget(){
  const target=document.getElementById('validation-target');
  const entry=fieldEntries.find(item=>String(item.id)===String(selectedEntryId)||String(item.localId)===String(selectedEntryId));
  const prompt=getValidationPrompt();
  if(!entry||!matchesValidationGeometry(entry)){if(target)target.textContent=prompt;return}
  if(entry.source!=='backend'){if(target)target.textContent=`Selected ${entry.cropName} for ${entry.ownerName}. Upload it to the server before validation.`;return}
  const geometryLabel=inferPrimaryModule(entry)==='livestock'?'GPS point':(entry.captureType==='point'?'point':'polygon');
  const geofenceText=entry.geofenceStatus?` | Geofence: ${String(entry.geofenceStatus).replace(/_/g,' ')}`:'';
  const reviewText=entry.reviewStatus?` | Review: ${String(entry.reviewStatus).replace(/_/g,' ')}`:'';
  if(target)target.textContent=`Validating ${geometryLabel} ${entry.cropName} for ${entry.ownerName}. Current status: ${entry.validationStatus||'uncertain'}${reviewText}${geofenceText}.`;
  document.getElementById('validation-status').value=entry.validationStatus||'uncertain';
  document.getElementById('confidence').value=String(entry.validationConfidence||3);
  document.getElementById('validation-note').value=entry.validationNote||'';
  try{updateValidationQueueSummary()}catch{}
}

