async function submitValidation(){const submitButton=document.querySelector('#validate-form-el button[type="submit"]');if(!hasRole('validator','admin')){setValidationSelectionMessage('Your role cannot submit validations.','warning');showCollectorFeedback('Validation tools are available only to validators and admins.','warning',{sticky:true});return}const entry=fieldEntries.find(item=>String(item.id)===String(selectedEntryId));if(!entry){setValidationSelectionMessage('Select a field entry first.','warning');return}if(entry.source!=='backend'){setValidationSelectionMessage('Upload the local record to the server before validation.','warning');return}if(!accessToken){setValidationSelectionMessage('Please sign in first.','warning');showCollectorFeedback('Please sign in first.','warning',{sticky:true});return}setBusyButtonState(submitButton,true,'<i data-feather="loader"></i> Submitting...');const nextEntryHint=findNextValidationEntry(entry.id);try{const r=await fetch(`${API_URL}/fields/${entry.id}/validate`,{method:'POST',headers:authHeaders({'Content-Type':'application/json'}),body:JSON.stringify({validation_status:document.getElementById('validation-status').value,confidence:Number(document.getElementById('confidence').value),note:document.getElementById('validation-note').value.trim()||null})});const data=await r.json();if(!r.ok)throw new Error(data.detail||'Validation failed');await loadEntries();setLastSyncMessage(`Validation submitted for field ${entry.id}`,'success');if(nextEntryHint&&(String(nextEntryHint.id)!==String(entry.id)||String(nextEntryHint.localId)!==String(entry.localId))){focusEntry(nextEntryHint.id||nextEntryHint.localId);setValidationSelectionMessage(`Validation saved. Moved to next ${nextEntryHint.captureType||inferCaptureType(nextEntryHint.geometry)||'feature'}.`,'info')}else{selectedEntryId=data.id;updateValidationTarget();setValidationSelectionMessage('Validation saved. No other matching feature is available right now.','warning')}setValidationSelectionMessage('Validation submitted successfully.','info')}catch(e){setLastSyncMessage(`Validation failed: ${e.message}`,'error');setValidationSelectionMessage(`Validation failed: ${e.message}`,'warning')}finally{setBusyButtonState(submitButton,false)}}
async function uploadEntry(localId){
  if(!hasRole('collector','admin'))return showCollectorFeedback('Your role cannot upload local records.','warning',{sticky:true});
  if(!isNetworkLikelyAvailable())return showCollectorFeedback('You are offline. The record remains safely stored locally and will sync when connection returns.','warning',{sticky:true});
  const queue=getLocalQueue().map(normalizeSyncMetadata);
  const rawEntry=queue.find(item=>String(item.localId)===String(localId));
  if(!rawEntry)return showCollectorFeedback('Local entry not found.','warning');
  if(!accessToken||(currentUser&&currentUser.isGuest))return showCollectorFeedback('Sign in first to upload local entries to the server.','warning',{sticky:true});
  const lockId=createStableLocalId('sync');
  markQueueItem(localId,{syncStatus:'in_progress',lastSyncError:'',lastSyncAttempt:getNowIso(),syncAttemptCount:(Number(rawEntry.syncAttemptCount)||0)+1,syncLockId:lockId});
  refreshSyncCounters();
  const entry=(window.normalizeLocalEntry||normalizeLocalEntry)({...rawEntry,syncStatus:'in_progress'});
  try{
    const r=await fetch(`${API_URL}/fields/sync`,{method:'POST',headers:authHeaders({'Content-Type':'application/json'}),body:JSON.stringify({items:[(window.buildSyncItem||buildSyncItem)(entry)]})});
    const data=await r.json().catch(()=>({detail:'Invalid server response'}));
    if(!r.ok)throw new Error(data.detail||'Upload failed');
    if(data.failed&&data.failed.length){
      const failure=data.failed[0];
      markQueueItem(localId,{syncStatus:'failed',syncLockId:null,lastSyncError:failure.error||'Upload failed',lastSyncAttempt:getNowIso()});
      await loadEntries();
      setLastSyncMessage(`Upload failed for ${localId}: ${failure.error||'Unknown error'}`,'error');
      return showCollectorFeedback(`Upload failed: ${failure.error||'Unknown error'}`,'error',{sticky:true});
    }
    removeQueuedEntry(localId);
    await loadEntries();
    setLastSyncMessage(`Uploaded local record ${localId} to server`,'success');
    showCollectorFeedback('Local entry uploaded to server.','success');
    return true;
  }catch(e){
    markQueueItem(localId,{syncStatus:'failed',syncLockId:null,lastSyncError:getSyncErrorMessage(e),lastSyncAttempt:getNowIso()});
    await loadEntries();
    setLastSyncMessage(`Upload failed: ${getSyncErrorMessage(e)}`,'error');
    showCollectorFeedback(`Upload failed: ${getSyncErrorMessage(e)}`,'error',{sticky:true});
    return false;
  }
}
async function pushAllPending(options={}){
  const {silent=false,reason='manual'}=options||{};
  const pushButton=document.getElementById('push-all-server');
  if(!hasRole('collector','admin')){
    if(!silent)return showCollectorFeedback('Your role cannot push local records to the server.','warning',{sticky:true});
    return false;
  }
  if(!isNetworkLikelyAvailable()){
    if(!silent)showCollectorFeedback('You are offline. Local records remain safely stored and will sync when connection returns.','warning',{sticky:true});
    return false;
  }
  const queue=getPendingSyncQueue();
  if(!queue.length){
    if(!silent)showCollectorFeedback('No pending local entries to upload.','info');
    return false;
  }
  if(!accessToken||(currentUser&&currentUser.isGuest)){
    if(!silent)return showCollectorFeedback('Sign in first to push local entries to the server.','warning',{sticky:true});
    return false;
  }
  if(!silent)setBusyButtonState(pushButton,true,'<i data-feather="loader"></i> Pushing...');
  const batchLockId=createStableLocalId('batch');
  const attemptTime=getNowIso();
  queue.forEach(entry=>markQueueItem(entry.localId,{syncStatus:'in_progress',lastSyncError:'',lastSyncAttempt:attemptTime,syncAttemptCount:(Number(entry.syncAttemptCount)||0)+1,syncLockId:batchLockId}));
  refreshSyncCounters();

  let uploaded=0;
  let failed=0;

  try{
    /*
      We sync one item at a time. This is slower than one big batch, but much safer:
      one bad record no longer causes all offline records to fail together.
    */
    for(const entry of queue){
      try{
        const normalized=(window.normalizeLocalEntry||normalizeLocalEntry)({...entry,syncStatus:'in_progress'});
        const r=await fetch(`${API_URL}/fields/sync`,{method:'POST',headers:authHeaders({'Content-Type':'application/json'}),body:JSON.stringify({items:[(window.buildSyncItem||buildSyncItem)(normalized)]})});
        const data=await r.json().catch(()=>({detail:'Invalid server response'}));
        if(!r.ok)throw new Error(data.detail||'Sync failed');
        if(data.failed&&data.failed.length){
          const failure=data.failed[0];
          throw new Error(failure.error||'Sync failed');
        }
        removeQueuedEntry(entry.localId);
        uploaded+=1;
      }catch(itemError){
        failed+=1;
        markQueueItem(entry.localId,{syncStatus:'failed',syncLockId:null,lastSyncError:getSyncErrorMessage(itemError),lastSyncAttempt:getNowIso()});
      }
    }
    await loadEntries();
    const remaining=getLocalQueue().filter(entry=>entry.syncStatus!=='synced').length;
    const type=failed?'warning':'success';
    setLastSyncMessage(`Push complete: ${uploaded} uploaded, ${failed} failed, ${remaining} remaining locally${silent?` (${reason})`:''}`,type);
    if(!silent)showCollectorFeedback(`Push complete. Uploaded ${uploaded} record(s), ${failed} failed, ${remaining} remaining locally.`,type,{sticky:!!failed});
    return failed===0;
  }catch(e){
    const message=getSyncErrorMessage(e);
    queue.forEach(entry=>markQueueItem(entry.localId,{syncStatus:'failed',syncLockId:null,lastSyncError:message,lastSyncAttempt:getNowIso()}));
    await loadEntries();
    setLastSyncMessage(`Push failed: ${message}`,'error');
    if(!silent)showCollectorFeedback(`Push failed: ${message}`,'error',{sticky:true});
    return false;
  }finally{
    if(!silent)setBusyButtonState(pushButton,false);
  }
}
async function archiveEntry(entryId){if(!hasRole('collector','admin'))return showCollectorFeedback('Your role cannot archive field records.','warning',{sticky:true});const entry=fieldEntries.find(item=>String(item.id)===String(entryId)&&item.source==='backend');if(!entry)return showCollectorFeedback('Only saved backend records can be archived here.','warning',{sticky:true});if(!confirm(`Archive ${entry.cropName} for ${entry.ownerName||'this field owner'}?`))return;try{const r=await fetch(`${API_URL}/fields/${entry.id}`,{method:'DELETE',headers:authHeaders()});const data=await r.json();if(!r.ok)throw new Error(data.detail||'Archive failed');await loadEntries();if(String(selectedEntryId)===String(entry.id))selectedEntryId=null;setLastSyncMessage(`Archived field ${entry.id}`,'warning');showCollectorFeedback('Record archived successfully. It is now hidden from the collector list and remains available to admins for restore.','warning',{sticky:true})}catch(e){setLastSyncMessage(`Archive failed: ${e.message}`,'error');showCollectorFeedback(`Archive failed: ${e.message}`,'error',{sticky:true})}}
