function groupEntriesByFarmer(entries){const groups=[];const seen=new Map();entries.forEach(entry=>{const key=getEntryGroupKey(entry);let group=seen.get(key);if(!group){group={key,label:entry.ownerName||entry.farmName||'Farmer not set',farmName:entry.farmName||'',surveyName:entry.surveyName||'',entries:[],totalArea:0,crops:new Set()};seen.set(key,group);groups.push(group)}group.entries.push(entry);group.totalArea+=Number(entry.area)||0;if(entry.cropName)group.crops.add(entry.cropName);if(!group.label&&entry.ownerName)group.label=entry.ownerName;if(!group.farmName&&entry.farmName)group.farmName=entry.farmName;if(!group.surveyName&&entry.surveyName)group.surveyName=entry.surveyName});groups.forEach(group=>group.entries.sort((a,b)=>(Number(a.plotNumber)||1)-(Number(b.plotNumber)||1)));return groups}
