function createFarmerGroupItem(group){const expanded=farmerGroupExpanded[group.key]!==false;const selected=selectedFarmerGroupKey===group.key;const cropList=[...group.crops];const cropSummary=cropList.length?`${cropList.slice(0,3).join(', ')}${cropList.length>3?' ...':''}`:'No crops yet';const li=document.createElement('li');li.style.listStyle='none';li.style.margin='0 0 .85rem';li.innerHTML=`<div class="status" style="margin:0;${selected?'border-color:#2e7d32;background:#eef6ef':''}"><div style="display:flex;justify-content:space-between;gap:.75rem;align-items:flex-start;flex-wrap:wrap"><div><strong style="display:block">${group.label}</strong><div style="margin-top:.35rem;font-size:.82rem;color:#5f6f5f">${group.surveyName||'Survey not set'}${group.farmName?` | ${group.farmName}`:''} | ${group.entries.length} plot${group.entries.length===1?'':'s'} | ${group.totalArea.toFixed(2)} ha</div><div style="margin-top:.25rem;font-size:.8rem;color:#6a7a6a">${cropSummary}</div></div><div style="display:flex;gap:.45rem;flex-wrap:wrap;justify-content:flex-end"><button type="button" class="secondary" data-act="select-group" style="width:auto;padding:.45rem .7rem">${selected?'Viewing':'Open Farmer'}</button><button type="button" class="secondary" data-act="toggle-group" style="width:auto;padding:.45rem .7rem">${expanded?'Hide Plots':'Show Plots'}</button></div></div></div><ul class="entries" data-group-plots style="margin-top:.65rem;padding-left:0;display:${expanded?'block':'none'}"></ul>`;const plotsList=li.querySelector('[data-group-plots]');group.entries.forEach(entry=>plotsList.appendChild(createEntryListItem(entry)));li.querySelector('[data-act="select-group"]').onclick=()=>{selectedFarmerGroupKey=selected?null:group.key;if(!selected)farmerGroupExpanded[group.key]=true;renderEntries()};li.querySelector('[data-act="toggle-group"]').onclick=()=>{farmerGroupExpanded[group.key]=!expanded;renderEntries()};return li}
function renderEntries(){const transientLayers=[];const transientSelected=selectedPolygon&&!isPersistedLayer(selectedPolygon)?selectedPolygon:null;drawnItems&&drawnItems.eachLayer(layer=>{if(!isPersistedLayer(layer))transientLayers.push(layer)});drawnItems&&drawnItems.clearLayers();const list=document.getElementById('fields-list');list.innerHTML='';const validationOnly=getActiveMode()==='validate'&&hasRole('validator','admin');const visibleEntries=validationOnly?fieldEntries.filter(entry=>entry.source==='backend'&&matchesValidationGeometry(entry)):fieldEntries;if(!visibleEntries.length){list.innerHTML=`<li class="empty">${validationOnly?`No synced ${getValidationGeometryLabel().toLowerCase()} available for validation yet.`:'No entries yet. Start a crop or livestock survey and save an entry.'}</li>`}visibleEntries.forEach(entry=>{if(entry.geometry){const geo=L.geoJSON({type:'Feature',geometry:entry.geometry,properties:{entryId:entry.id,localId:entry.localId}},{pointToLayer:(_,latlng)=>L.marker(latlng),style:getDefaultFeatureStyle()});geo.eachLayer(l=>{l.feature=l.feature||{type:'Feature',properties:{}};l.feature.properties.entryId=entry.id;l.feature.properties.localId=entry.localId;drawnItems.addLayer(l);attachLayer(l)})}});if(visibleEntries.length){if(validationOnly){visibleEntries.forEach(entry=>list.appendChild(createEntryListItem(entry)))}else{groupEntriesByFarmer(visibleEntries).forEach(group=>list.appendChild(createFarmerGroupItem(group)))}}transientLayers.forEach(layer=>{drawnItems.addLayer(layer);attachLayer(layer)});if(transientSelected&&drawnItems.hasLayer(transientSelected)){selectedPolygon=transientSelected;if(selectedPolygon.setStyle)selectedPolygon.setStyle(getSelectedFeatureStyle());document.getElementById('save-entry-btn').style.display='flex';document.getElementById('select-polygon-btn').style.display='none';setSaveNextPlotButtonVisibility(true)}document.getElementById('field-count').textContent=`${visibleEntries.length} / ${fieldEntries.length}`;updateValidationTarget();updateRemoveShapeButton();refreshSyncCounters();updateFarmerSummaryPanel();updateFarmerDetailPanel();updateMobileSaveFlowState();feather.replace()}
function focusEntry(id){selectedEntryId=id;const layers=[];drawnItems.eachLayer(l=>{if(l.feature&&l.feature.properties&&(String(l.feature.properties.entryId)===String(id)||String(l.feature.properties.localId)===String(id))){layers.push(l);l.setStyle&&l.setStyle(getSelectedFeatureStyle());selectedPolygon=l;autofillLocation(l)}});updateRemoveShapeButton();if(layers.length){const group=L.featureGroup(layers);if(group.getBounds().isValid())map.fitBounds(group.getBounds(),{padding:[30,30]})}updateValidationTarget()}
function collectionGeoJSON(){return{type:'FeatureCollection',features:fieldEntries.filter(e=>!!e.geometry).map(e=>({type:'Feature',geometry:e.geometry,properties:{id:e.id||e.localId,primary_module:inferPrimaryModule(e),survey_name:e.surveyName,owner_name:e.ownerName,farm_name:e.farmName,questionnaire_id:e.questionnaireId,aeo_name:e.aeoName,aeo_contact_number:e.aeoContactNumber,farmer_contact:e.farmerContact,aez:e.aez,gender_hhh:e.genderHhh,gender_decision_maker:e.genderDecisionMaker,age_hhh:e.ageHhh,marital_status_hhh:e.maritalStatusHhh,education_level_hhh:e.educationLevelHhh,has_disability:e.hasDisability,disability_condition:e.disabilityCondition,hh_size_0_17:e.hhSize017,hh_size_18_35:e.hhSize1835,hh_size_36_60:e.hhSize3660,hh_size_60_plus:e.hhSize60Plus,total_owned_land_holding_ha:e.totalOwnedLandHoldingHa,owned_arable_land_ha:e.ownedArableLandHa,land_rented_from_others_ha:e.landRentedFromOthersHa,land_rented_to_others_ha:e.landRentedToOthersHa,total_area_planted_all_crops_ha:e.totalAreaPlantedAllCropsHa,cropped_area_with_contours_ha:e.croppedAreaWithContoursHa,first_successful_planting_dekad:e.firstSuccessfulPlantingDekad,planting_window:e.plantingWindow,seed_kg:e.seedKg,basal_dressing_kg:e.basalDressingKg,top_dressing_kg:e.topDressingKg,lime_kg:e.limeKg,confirm_total_area_planted:e.confirmTotalAreaPlanted,seed_type:e.seedType,major_variety:e.majorVariety,write_off:e.writeOff,write_off_area_ha:e.writeOffAreaHa,write_off_cause:e.writeOffCause,write_off_other_cause:e.writeOffOtherCause,gap_filling:e.gapFilling,area_replanted_ha:e.areaReplantedHa,major_input_source:e.majorInputSource,province:e.province,district:e.district,ward:e.ward,farmer_group_id:e.farmerGroupId,plot_number:e.plotNumber,location_name:e.locationName,sector_code:e.sector,sector_label:e.sectorLabel||e.sector,capture_type:e.captureType,geofence_status:e.geofenceStatus||'',gps_verified:!!e.gpsVerified,gps_latitude:e.gpsLatitude??null,gps_longitude:e.gpsLongitude??null,gps_accuracy_m:e.gpsAccuracyMeters??null,distance_to_field_m:e.distanceToFieldMeters??null,geofence_requires_review:!!e.geofenceRequiresReview,geofence_message:e.geofenceMessage||'',crop_type_code:e.cropType,crop_type_label:e.cropName,crop_condition_code:e.cropCondition,crop_condition_label:e.cropConditionLabel||e.cropCondition,growth_stage_code:e.growthStage,growth_stage_label:e.growthStageLabel||e.growthStage,season_code:e.season,season_label:e.seasonLabel||e.season,irrigation_type_code:e.irrigationType,irrigation_type_label:e.irrigationTypeLabel||e.irrigationType,planting_date:e.plantingDate,harvest_date:e.harvestDate,yield_expected:e.yieldExpected,yield_tonnes:e.yieldTonnes,observation_notes:e.observationNotes,post_harvest_assessment:e.postHarvestAssessment,photo_name:e.photoName||null,area_hectares:e.area,validation_status:e.validationStatus,review_status:e.reviewStatus,sync_status:e.syncStatus,notes:e.notes,source:e.source}}))}}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url)}
function exportCSV(){if(!fieldEntries.length)return showCollectorFeedback('No data to export yet. Save at least one record first.','warning',{sticky:true});let csv='ID,Survey Name,Questionnaire ID,Owner,Farm,AEO Name,AEO Contact,Farmer Contact,AEZ,Gender HHH,Decision Maker Gender,Age HHH,Marital Status HHH,Education Level HHH,Has Disability,Disability Condition,HH Size 0-17,HH Size 18-35,HH Size 36-60,HH Size 60+,Total Owned Land Holding (ha),Owned Arable Land (ha),Land Rented From Others (ha),Land Rented To Others (ha),Total Area Planted All Crops (ha),Cropped Area With Contours (ha),First Successful Planting Dekad,Planting Window,Seed (kg),Basal Dressing (kg),Top Dressing (kg),Lime (kg),Confirm Total Area Planted,Seed Type,Major Variety,Write Off,Write Off Area (ha),Write Off Cause,Other Write Off Cause,Gap Filling,Area Replanted (ha),Major Input Source,Province,District,Ward,Farmer Group ID,Plot Number,Location,Sector Code,Sector,Capture Type,Crop Type Code,Crop Type,Growth Stage Code,Growth Stage,Crop Condition Code,Crop Condition,Season Code,Season,Irrigation Code,Irrigation,Planting Date,Harvest Date,Yield Expected,Yield Tonnes,Area (ha),Validation,Supervisor Review,Photo Name,Source,Observation Notes,Post Harvest Assessment,Notes\n';fieldEntries.forEach(e=>csv+=`"${e.id}","${e.surveyName||''}","${e.questionnaireId||''}","${e.ownerName||''}","${e.farmName||''}","${e.aeoName||''}","${e.aeoContactNumber||''}","${e.farmerContact||''}","${e.aez||''}","${e.genderHhh||''}","${e.genderDecisionMaker||''}","${e.ageHhh??''}","${e.maritalStatusHhh||''}","${e.educationLevelHhh||''}","${e.hasDisability||''}","${e.disabilityCondition||''}","${e.hhSize017??''}","${e.hhSize1835??''}","${e.hhSize3660??''}","${e.hhSize60Plus??''}","${e.totalOwnedLandHoldingHa??''}","${e.ownedArableLandHa??''}","${e.landRentedFromOthersHa??''}","${e.landRentedToOthersHa??''}","${e.totalAreaPlantedAllCropsHa??''}","${e.croppedAreaWithContoursHa??''}","${e.firstSuccessfulPlantingDekad||''}","${e.plantingWindow||''}","${e.seedKg??''}","${e.basalDressingKg??''}","${e.topDressingKg??''}","${e.limeKg??''}","${e.confirmTotalAreaPlanted||''}","${e.seedType||''}","${e.majorVariety||''}","${e.writeOff||''}","${e.writeOffAreaHa??''}","${e.writeOffCause||''}","${e.writeOffOtherCause||''}","${e.gapFilling||''}","${e.areaReplantedHa??''}","${e.majorInputSource||''}","${e.province||''}","${e.district||''}","${e.ward||''}","${e.farmerGroupId||''}","${e.plotNumber||1}","${e.locationName||''}","${e.sector||''}","${e.sectorLabel||''}","${e.captureType||''}","${e.cropType||''}","${e.cropName||''}","${e.growthStage||''}","${e.growthStageLabel||''}","${e.cropCondition||''}","${e.cropConditionLabel||''}","${e.season||''}","${e.seasonLabel||''}","${e.irrigationType||''}","${e.irrigationTypeLabel||''}","${e.plantingDate||''}","${e.harvestDate||''}","${e.yieldExpected||''}","${e.yieldTonnes||''}","${e.area||''}","${e.validationStatus||''}","${e.reviewStatus||'pending_review'}","${e.photoName||''}","${e.source}","${(e.observationNotes||'').replace(/\"/g,'\"\"')}","${(e.postHarvestAssessment||'').replace(/\"/g,'\"\"')}","${(e.notes||'').replace(/\"/g,'\"\"')}"\n`);downloadBlob(new Blob([csv],{type:'text/csv'}),`crop_collector_${new Date().toISOString().slice(0,10)}.csv`)}
function exportGeoJSON(){if(!fieldEntries.length)return showCollectorFeedback('No data to export yet. Save at least one record first.','warning',{sticky:true});downloadBlob(new Blob([JSON.stringify(collectionGeoJSON(),null,2)],{type:'application/json'}),`crop_collector_${new Date().toISOString().slice(0,10)}.geojson`)}
function exportKML(){if(!fieldEntries.length)return showCollectorFeedback('No data to export yet. Save at least one record first.','warning',{sticky:true});let kml='<?xml version="1.0" encoding="UTF-8"?>\n<kml xmlns="http://www.opengis.net/kml/2.2"><Document><name>Crop Collector Data</name>';fieldEntries.forEach(e=>{kml+=`<Placemark><name>${e.cropName}</name><description><![CDATA[Survey: ${e.surveyName||'-'}<br/>Owner: ${e.ownerName||'-'}<br/>Farm: ${e.farmName||'-'}<br/>Location: ${e.locationName||'-'}<br/>Sector: ${e.sectorLabel||e.sector||'-'}<br/>Growth Stage: ${e.growthStageLabel||e.growthStage||'-'}<br/>Condition: ${e.cropConditionLabel||e.cropCondition||'-'}<br/>Area: ${e.area||'0.00'} ha<br/>Notes: ${e.notes||'-'}]]></description>`+(e.geometry.type==='Point'?`<Point><coordinates>${e.geometry.coordinates[0]},${e.geometry.coordinates[1]},0</coordinates></Point>`:(`<Polygon><outerBoundaryIs><LinearRing><coordinates>`+e.geometry.coordinates[0].map(c=>`${c[0]},${c[1]},0 `).join('')+`</coordinates></LinearRing></outerBoundaryIs></Polygon>`))+`</Placemark>`});kml+='</Document></kml>';downloadBlob(new Blob([kml],{type:'application/vnd.google-earth.kml+xml'}),`crop_collector_${new Date().toISOString().slice(0,10)}.kml`)}
async function exportShapefile(){if(currentUser&&currentUser.isGuest)return showCollectorFeedback('Sign in first to export a backend shapefile ZIP.','warning',{sticky:true});if(!accessToken)return showCollectorFeedback('Please sign in first.','warning',{sticky:true});try{const r=await fetch(`${API_URL}/export/shapefile`,{headers:{Authorization:`Bearer ${accessToken}`}});if(!r.ok){let message='Shapefile export failed.';try{const data=await r.json();message=data.detail||message}catch{}throw new Error(message)}const blob=await r.blob();const disposition=r.headers.get('content-disposition')||'';const match=/filename=([^;]+)/i.exec(disposition);const filename=match?match[1].replace(/"/g,'').trim():'crop_collector_shapefile.zip';downloadBlob(blob,filename);showCollectorFeedback('Shapefile export downloaded successfully.','success')}catch(e){showCollectorFeedback(`Shapefile export failed: ${e.message}`,'error',{sticky:true})}}
